-- جزء 3 من 4 — نماذج modell-05–modell-06
-- مولّد من supabase/seed/b2.sql بـtools/split_seed.sh — لا تعدّله بالإيد
-- آمن للإعادة: شغّله مرتين ما بيغيّر شي.

begin;

-- مولّد من content/telc/b2 بـtools/export_sql.py — لا تعدّله بالإيد

insert into levels (id, title, sort, published, provider, stufe) values ('telc-b2', 'telc Deutsch B2', 0, true, 'telc', 'B2')
on conflict (id) do update set title = excluded.title,
  provider = coalesce(levels.provider, excluded.provider),
  stufe    = coalesce(levels.stufe,    excluded.stufe);

-- ================= modell-05 · BETRIEBSSPORT =================
insert into tests (level_id, slug, title, subtitle, blocks, aufgaben, published, sort)
values ('telc-b2', 'modell-05', 'BETRIEBSSPORT', '53 Aufgaben · 125 Minuten',
        '[{"id": "block-lesen", "parts": ["lv1", "lv2", "lv3", "lv4"], "title": "Lesen", "minutes": 45, "hint": "Aufgaben 1–18", "maxPoints": 54, "availablePoints": 54, "missing": 0}, {"id": "block-lesen-schreiben", "parts": ["lvs1", "lvs2"], "title": "Lesen und Schreiben", "minutes": 20, "hint": "Aufgaben 19–20 und Beschwerde", "maxPoints": 13, "availablePoints": 13, "missing": 0}, {"id": "block-hoeren", "parts": ["hv1", "hv2", "hv3", "hv4"], "title": "Hören", "minutes": 20, "hint": "Aufgaben 22–40", "maxPoints": 57, "availablePoints": 57, "missing": 0}, {"id": "block-hoeren-schreiben", "parts": ["hvs"], "title": "Hören und Schreiben", "minutes": 5, "hint": "Aufgabe 41 und Telefonnotiz", "maxPoints": 9, "availablePoints": 9, "missing": 0}, {"id": "block-sb", "parts": ["sb1", "sb2"], "title": "Sprachbausteine", "minutes": 35, "hint": "Aufgaben 46–57", "maxPoints": 6, "availablePoints": 6, "missing": 0}]'::jsonb, 53, true, 5)
on conflict (level_id, slug) do update set title = excluded.title, subtitle = excluded.subtitle, blocks = excluded.blocks, aufgaben = excluded.aufgaben, sort = excluded.sort;

insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Hilfe für Betroffene: Beleidigungen, Ausgrenzung, versteckte Drohungen – am Arbeitsplatz ist Mobbing leider weit verbreitet. Für viele Angestellte ist der Arbeitsalltag oft mit Angst verbunden. Inzwischen gibt es zahlreiche Coaching-Programme für Mitarbeiter, die Strategien aufzeigen, wie man mit solchen Situationen besser umgehen kann."}, {"key": "B", "text": "Ein starkes Team: Pünktlich zum Start der Weltmeisterschaft präsentiert der Handballbund seine neue Vertragspartnerin, die deutsche Handwerkskammer. „Was für den Handballer die Weltmeisterschaft ist, ist für den Handwerker die Meisterprüfung.\""}, {"key": "C", "text": "Deutsche sind risikoscheu: In Deutschland ist die Zahl der Unternehmensgründungen stark rückläufig, obwohl viele jüngere Menschen angeben, dass sie sich gerne selbstständig machen würden. Warum der Sprung in die Selbstständigkeit oft doch nicht klappt, hat vielerlei Gründe."}, {"key": "D", "text": "Handwerk und Karriere – passt das? Fleischer, Klempner, Tischler – laut Bundesagentur für Arbeit werden ca. 150.000 Handwerker gesucht. Handwerksberufe bieten gerade jungen Leuten nach dem Schulabschluss beste Chancen für eine krisensichere Zukunft."}, {"key": "E", "text": "Stressfrei zum Ziel: Auch Fortbildungen können für eine Meisterprüfung im Handwerk anerkannt werden. Wenn Sie z. B. als Kfz-Servicetechniker einen Kurs in Elektronik erfolgreich absolviert haben, wird dieser Teil nicht noch einmal gesondert geprüft."}, {"key": "F", "text": "Nie wieder Opfer: Sie wurde in ihrer Firma gemobbt und konnte es ihrem Chef nicht nachweisen. Die Autorin Stephanie Hauser verarbeitet in ihrem Roman „Nie wieder Opfer\" auf eindrucksvolle Weise ihre eigenen Erfahrungen zum Thema Mobbing."}, {"key": "G", "text": "Verpflichtend oder freiwillig: Die Anforderungen der Berufswelt ändern sich rasant. Prinzipiell gilt, dass Mitarbeiter zur Teilnahme an Seminaren verpflichtet sind, wenn diese zur Ausübung ihrer Tätigkeit notwendig sind und in der normalen Arbeitszeit stattfinden."}, {"key": "H", "text": "Karriereplan für eine vielversprechende Laufbahn: Vor allem in Großstädten bieten immer mehr junge Unternehmen interessante Jobmöglichkeiten. Auch bei jungen Start-up-Unternehmen finden Absolventen gute Entwicklungschancen."}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 12, 'Lesen Sie den Text und die Aufgaben 6–9. Entscheiden Sie, welche Lösung richtig ist.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Text 1: Betriebssport", "b": true}, {"t": "Sportliche Aktivitäten werden bei uns großgeschrieben. So bieten wir unseren Mitarbeitern im Untergeschoss einen Fitnessraum mit Bodenmatten und mehreren Fitnessgeräten, wie z. B. zwei Indoor-Fahrradtrainern. Dieser ist für alle ganztägig frei und ohne Gebühr zugänglich und kann selbstverständlich auch in den Pausen genutzt werden.", "b": false}, {"t": "Außerdem nehmen wir als Unternehmen jedes Jahr am städtischen Firmenlauf teil. Es hat sich die Tradition entwickelt, dass sich die teilnehmenden Kolleginnen und Kollegen gemeinsam in einem wöchentlichen Lauftreff auf dieses Event vorbereiten. Dieser findet jeden Mittwoch um 17:30 Uhr statt.", "b": false}, {"t": "Abwechslungsreich gestaltete Arbeitsplätze in den Büros tragen zur Steigerung der Aktivität auch während der Arbeit bei und wirken den negativen Auswirkungen langen Sitzens entgegen. Alle Schreibtische sind höhenverstellbar, sodass Arbeiten auch im Stehen möglich ist. Zusätzlich bieten wir das sogenannte „Deskbike\" an – eine Art Büro-Fahrrad, das sich einfach unter einen höhenverstellbaren Schreibtisch rollen lässt.", "b": false}, {"t": "Text 2: Berichtsheft", "b": true}, {"t": "Das Berichtsheft ist der Nachweis, dass die Ausbildung ordnungsgemäß verläuft. In diesem wird alles dokumentiert, was man während der Ausbildung macht und lernt. Sie sollten nicht nur Ihre Tätigkeiten im Betrieb beschreiben, sondern auch alle Einweisungen, Schulungen und den innerbetrieblichen Unterricht vermerken.", "b": false}, {"t": "Es ist Pflicht, das Berichtsheft jeweils vor der Zwischen- und der Abschlussprüfung vorzulegen. Nur wenn es vollständig ist, wird der Prüfungsausschuss Sie zu den Prüfungen zulassen. Wenn Sie zwischen zwei Noten stehen, können Ihre Berichte sogar Ihre Endnote beeinflussen.", "b": false}, {"t": "Neben den Wochenberichten, die Sie jeden Freitag an Ihren Teamleiter schicken, müssen Sie nach dem Durchlaufen einer Abteilung einen zusätzlichen Bericht verfassen. Sie dürfen Ihre Berichte während der Arbeitszeit schreiben und können sie sowohl in klassischer Heftform als auch digital einreichen. In festen Abständen haben Sie das Heft Ihrem Ausbildungsleiter zur Kenntnisnahme vorzulegen.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Forumsbeiträge a–f. Welcher Beitrag passt zu welcher Situation? Wenn kein Beitrag passt, wählen Sie X.', 'matching', '{"bank": [{"key": "A", "text": "Hans: Der Arbeitgeber hat eine Fürsorgepflicht und dazu gehört auch, dass er für Fahrzeuge der Mitarbeiter eine Unterbringungsmöglichkeit zu schaffen hat. Aber nur, wenn das ohne zu großen Aufwand geht. Wenn ein Unternehmen in der Innenstadt ist, gibt es einfach nicht genug Platz für Parkmöglichkeiten."}, {"key": "B", "text": "Thilo: Wenn die Bahn wegen eines Sturms nicht weiterfahren kann und im Bahnhof stehen bleibt, haben die Fahrgäste meistens Anspruch auf einen Taxigutschein. Du kannst auf der Webseite der Bahn nachlesen, unter welchen Umständen die Kosten übernommen werden."}, {"key": "C", "text": "Johannes: Wenn du auf dem Weg zur Arbeit einen Autounfall hast, bezahlt die Unfallversicherung nur Personenschäden. Sachschäden sind dabei nicht inbegriffen."}, {"key": "D", "text": "Jacqueline: Du bist dafür verantwortlich, rechtzeitig an deinem Arbeitsplatz zu erscheinen. Wie du das machst, ist deine Sache. Aber du kannst keinesfalls die Verantwortung auf die öffentlichen Verkehrsmittel schieben."}, {"key": "E", "text": "Andreij: Natürlich hast du an deinem Arbeitsplatz Versicherungsschutz, aber dieser gilt nicht in allen Teilen des Gebäudes. Auf der Toilette bist du zum Beispiel nicht versichert."}, {"key": "F", "text": "Alex: Als Arbeitnehmer musst du dafür sorgen, zum Job zu kommen. Wenn das nicht geht, darfst du aber keine Abmahnung bekommen. Ob du ein Taxi nehmen musst, kommt darauf an, ob die Kosten über deinem Tagesarbeitslohn liegen. Wenn ja, sind sie nicht zumutbar."}, {"key": "X", "text": "Kein Beitrag passt."}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 13, 'Lesen Sie das Protokoll und die Aufgaben 14–18. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll 05.02.20XX, 14:00–16:00 Uhr", "b": true}, {"t": "Sitzungsraum: 239, Ort: Hauptstraße 23, 25421 Pinneberg", "b": false}, {"t": "Anwesende: Michael Müller (MM, Stellvertreter Geschäftsleitung), Katrin Wagner (KW, Leitung Personal), Henry Schulz (HS, Leitung Produktion), Klaus Seifert (KS, Leitung Verwaltung), Karl Lehmann (KL, Leitung Logistik)", "b": false}, {"t": "Protokollantin: Katrin Wagner. Sitzungsleitung: Michael Müller.", "b": false}, {"t": "Tagesordnungspunkte:", "b": false}, {"t": "1. Begrüßung und Genehmigung des Protokolls der letzten Sitzung", "b": false}, {"t": "2. Verpackungsmaterial und Spedition", "b": false}, {"t": "3. Personalsituation in der Produktion", "b": false}, {"t": "4. Sanierung der Kantine", "b": false}, {"t": "5. Neue Krankmeldungsregelung (vorgezogener TOP)", "b": false}, {"t": "6. Sonstiges", "b": false}, {"t": "TOP 1 Begrüßung: MM eröffnet die Sitzung. Das Protokoll der letzten Besprechung wird ohne Änderungen genehmigt. Wegen eines Anschlusstermins von KW wird TOP 5 vorgezogen.", "b": false}, {"t": "TOP 2 Verpackungsmaterial und Spedition: KL berichtet von Beschwerden über beschädigte Waren bei der Auslieferung. Er wird beauftragt, mit der beauftragten Spedition Kontakt aufzunehmen und gleichzeitig Angebote für stabileres Verpackungsmaterial einzuholen.", "b": false}, {"t": "TOP 3 Personalsituation in der Produktion: HS berichtet, dass dank Zeitarbeitskräften der personelle Engpass behoben werden konnte. Er regt an, zwei besonders zuverlässige Zeitarbeitskräfte fest anzustellen.", "b": false}, {"t": "TOP 4 Sanierung der Kantine: KS macht darauf aufmerksam, dass die Küche ab Montag saniert wird und die Kantine für sechs bis acht Wochen geschlossen bleibt. Mitarbeiter können eigene Verpflegung mitbringen oder das Bistro „Suppenkasper\" nutzen, wo die firmeneigenen Essensmarken von 12:00 bis 14:00 Uhr akzeptiert werden.", "b": false}, {"t": "TOP 5 Neue Krankmeldungsregelung: Die Geschäftsleitung verlangt zukünftig bereits ab dem ersten Krankheitstag ein ärztliches Attest. Da dies für Unmut sorgt, sollen die Abteilungsleiter den Mitarbeitern die Gründe nochmals vermitteln.", "b": false}, {"t": "TOP 6 Sonstiges: Ab kommenden Monat entstehen neben Eingang C zusätzliche Mitarbeiterparkplätze, die kostenlos in der Personalabteilung beantragt werden können.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19–20. Welche Lösung ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Beschwerde über Büroumzug", "b": true}, {"t": "Sehr geehrte Frau Börne,", "b": false}, {"t": "am Wochenende ist unser Büro mit Hilfe Ihres Unternehmens von Hanau nach Frankfurt umgezogen. Leider waren wir mit Ihrem Service überhaupt nicht zufrieden.", "b": false}, {"t": "Ihre Mitarbeiter kamen eine halbe Stunde zu spät und nur zu dritt statt wie vereinbart zu viert. Deshalb dauerte der ganze Umzug natürlich länger als geplant und einige Arbeiten sind auch noch nicht abgeschlossen: Es sind noch nicht alle Möbel aufgebaut, weshalb wir unsere Sachen noch nicht einräumen konnten.", "b": false}, {"t": "Bitte schicken Sie uns am Mittwochmorgen noch zwei Personen, die den Möbelaufbau erledigen. Des Weiteren sind Glasplatten zu Bruch gegangen und Schränke verkratzt. Ich gehe davon aus, dass Ihre Firma die Kosten dafür übernimmt.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Thomas Zaun", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf die Beschwerde.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrer Vorgesetzten:", "b": true}, {"t": "Hallo Frau Kühne, bitte schauen Sie sich die E-Mail von Herrn Zaun an. Schreiben Sie ihm und erklären Sie, warum es zu den Fehlern kam (Autopanne und kurzfristige Krankmeldungen). Sagen Sie ihm zu, dass am Mittwochmorgen pünktlich zwei Mitarbeiter für den Aufbau da sein werden und wir die Verantwortung sowie die Kosten für die Schäden übernehmen. Danke, Frieda Börne.", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Aussagen. Welche Aussage a–f passt zu welcher Person 28–31?', 'matching', '{"bank": [{"key": "A", "text": "Regelungen zur Arbeitsunfähigkeit unterscheiden sich von Unternehmen zu Unternehmen."}, {"key": "B", "text": "Die Arbeitsplatzgestaltung hat einen Einfluss auf die Gesundheit der Mitarbeiter."}, {"key": "C", "text": "Arbeitgeber sollten mehr für die Hygiene im Betrieb tun."}, {"key": "D", "text": "Manche Arbeitgeber bieten Maßnahmen für die Gesundheitsvorsorge an."}, {"key": "E", "text": "Das Wohlbefinden der Mitarbeiter sollte ein wichtiges Anliegen sein."}, {"key": "F", "text": "Bei Krankheit braucht man ab dem ersten Tag ein Attest vom Arzt."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 5, 'Sie hören eine Information der Geschäftsleitung über eine neue Filiale. Wählen Sie für die Aufgaben 32–35 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 4, 'Sie hören fünf Ansagen auf der Mailbox. Wählen Sie für die Aufgaben 36–40 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben, Telefonnotiz', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Tischreservierung Geschäftsessen", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Herrn Messner:", "b": false}, {"t": "„Guten Tag, hier spricht Nikol Meßner von der Firma Karcher & Söhne, buchstabiert M-E-S-S-N-E-R. Ich möchte für kommenden Freitagabend um 19:30 Uhr eine Tischreservierung für fünf Personen vornehmen. Es handelt sich um ein Geschäftsessen für unseren Chef und vier Kunden. Bitte bereiten Sie für alle Gäste das Menü Nr. 1 vor. Außerdem würde ich gerne wissen, ob Parkmöglichkeiten für unsere Gäste zur Verfügung stehen. Bitte rufen Sie mich zurück, um die Reservierung zu bestätigen. Meine Telefonnummer lautet 04133 784 30 09. Vielen Dank und auf Wiedersehen.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9, "audio": "telc-b2-m05-hvs.mp3", "audioPlays": 2}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–j passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "WORÜBER"}, {"key": "B", "text": "BEREITS"}, {"key": "C", "text": "EVENTUELL"}, {"key": "D", "text": "IN"}, {"key": "E", "text": "MANCHMAL"}, {"key": "F", "text": "DARAUF"}, {"key": "G", "text": "UNTER"}, {"key": "H", "text": "WAS"}, {"key": "I", "text": "NOCH"}, {"key": "J", "text": "ZUM"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Einladung zum Probearbeiten", "b": true}, {"t": "Sehr geehrte Frau Sabani,", "b": false}, {"t": "es freut mich sehr, dass ich in meinem Vorstellungsgespräch einen ersten positiven Eindruck hinterlassen habe und Sie mich (46) Probearbeiten einladen. Natürlich nutze ich sehr gern diese Gelegenheit, meine Fähigkeiten (47) Beweis zu stellen.", "b": false}, {"t": "Von den beiden Terminvorschlägen, die Sie mir geschickt haben, passt mir der nächste Dienstag am besten. Ich freue mich (48), bei dieser Gelegenheit (49) einen ersten Einblick in die Arbeitsabläufe und Abteilungen in Ihrem Haus zu bekommen.", "b": false}, {"t": "Stellen Sie mir die Arbeitskleidung für diesen Tag zur Verfügung oder soll ich selbst spezielle Kleidung mitbringen? Gibt es noch irgendwas, (50) ich vorher besorgen muss? Brauche ich (51) noch eine ärztliche Bescheinigung vom Gesundheitsamt?", "b": false}, {"t": "Danke im Voraus für eine kurze Beantwortung meiner Fragen.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Auftragsbestätigung", "b": true}, {"t": "Sehr geehrte Frau Mackbock,", "b": false}, {"t": "ich danke Ihnen für Ihre Bestellung und bestätige hiermit die Zustellung des PKW Bulldog zum Preis von 1078 Euro zzgl. MwSt. an die von (52) Lieferadresse. Sollte Ihre Rechnungsadresse nicht mit der Lieferadresse übereinstimmen, teilen Sie uns dies bitte bis spätestens 07.07. schriftlich mit.", "b": false}, {"t": "Die Rechnungszustellung erfolgt per Post. Bitte beachten Sie, dass wir bei Zahlung des Kaufpreises innerhalb von sieben Tagen nach Lieferung (53). Ansonsten muss der Rechnungsbetrag bis 30 Tage nach Wareneingang (54).", "b": false}, {"t": "Die detaillierten Konditionen (55) unseren allgemeinen Geschäftsbedingungen auf der Rückseite dieser Auftragsbestätigung.", "b": false}, {"t": "Bei Rückfragen steht Ihnen unser 24-Stunden-Service unter der Rufnummer 0175 545621 zur Verfügung. Bitte halten Sie hierzu Ihre (56).", "b": false}, {"t": "Wir versprechen Ihnen eine zuverlässige (57) und sind sicher, dass Sie mit unserem Produkt zufrieden sein werden.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Christoph Sellert", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-05'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Yasmina sucht nach dem Realschulabschluss einen Beruf mit guten Perspektiven.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Jason überlegt, ob er bei einem neu gegründeten Unternehmen arbeiten soll.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Hannah wird von ihren Kollegen schlecht behandelt und sucht Hilfe.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Gacer fragt sich, ob sie Fortbildungen besuchen muss.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Assem braucht Informationen zur Meisterprüfung.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Der Fitnessraum ist während der Arbeitszeit geöffnet.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'Die Mitarbeiter', '[{"key": "A", "text": "erhalten einen Zuschuss für ein Deskbike."}, {"key": "B", "text": "haben teilweise spezielle Schreibtische in Stehhöhe."}, {"key": "C", "text": "können das hausinterne Fitnessstudio gratis nutzen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Auszubildende ohne ordentlich geführtes Berichtsheft dürfen nicht an der Abschlussprüfung teilnehmen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Das Berichtsheft muss', '[{"key": "A", "text": "in der Freizeit geführt werden."}, {"key": "B", "text": "dem Ausbildungsleiter regelmäßig gezeigt werden."}, {"key": "C", "text": "jeden Tag ausgefüllt werden."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Mikke: Heute hatte ich auf dem Weg zur Arbeit einen Unfall. Ich habe noch einen Umweg über die Kita gemacht, bin gestolpert und habe mir den Knöchel gebrochen. Bin ich denn jetzt versichert?', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Ludmilla: Ich habe eine Abmahnung bekommen, weil ich regelmäßig zu spät zur Arbeit komme. Ich finde bei der Firma keine Parkmöglichkeit. Muss der Arbeitgeber nicht Parkplätze stellen?', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Peter: Ich wollte heute Morgen mit der S-Bahn zur Arbeit fahren, aber diese ist wegen Unwetters ausgefallen. Ich habe kein Auto. Hätte ich ein Taxi nehmen müssen?', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Ingo: Der Bus kommt zu spät oder fällt aus. Jetzt habe ich Ärger mit dem Chef. Bin ich verpflichtet, immer einen früheren Bus zu nehmen, damit ich pünktlich bin?', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Frau Wagner', '[{"key": "A", "text": "bittet um Änderungen des Protokolls vom letzten Treffen."}, {"key": "B", "text": "hat heute noch einen anderen wichtigen Termin."}, {"key": "C", "text": "schlägt einen zusätzlichen Tagesordnungspunkt vor."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Die Geschäftsleitung möchte, dass', '[{"key": "A", "text": "das Thema Krankmeldung nicht mehr besprochen wird."}, {"key": "B", "text": "man bei Krankheit spätestens am dritten Tag zum Arzt geht."}, {"key": "C", "text": "sich Mitarbeiter bei Krankheit sofort ab dem ersten Tag krankschreiben lassen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Karl Lehmann soll', '[{"key": "A", "text": "eigenständig teures Verpackungsmaterial einkaufen."}, {"key": "B", "text": "einen detaillierten Finanzierungsplan erstellen."}, {"key": "C", "text": "Kontakt mit der Spedition aufnehmen."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'In der Produktionsabteilung', '[{"key": "A", "text": "gibt es derzeit dank Zeitarbeitskräften genügend Personal."}, {"key": "B", "text": "will man alle Zeitarbeiter fest anstellen."}, {"key": "C", "text": "wurden zwei neue Mitarbeiter bereits fest eingestellt."}]'::jsonb, 3, null::jsonb, 3),
    ('lv4', '18', 'In der Kantine', '[{"key": "A", "text": "bekommt man in den kommenden Wochen kein Essen."}, {"key": "B", "text": "kann man ab Montag von 12 bis 14 Uhr warm zu Mittag essen."}, {"key": "C", "text": "sollen die Essensmarken abgeschafft werden."}]'::jsonb, 3, null::jsonb, 4),
    ('lvs1', '19', 'Beim Umzug', '[{"key": "A", "text": "haben vier Möbelpacker gearbeitet."}, {"key": "B", "text": "kam es zu Verzögerungen."}, {"key": "C", "text": "wurden nicht alle Möbel transportiert."}]'::jsonb, 3, null::jsonb, 0),
    ('lvs1', '20', 'Herr Zaun', '[{"key": "A", "text": "musste seinen Umzug verschieben."}, {"key": "B", "text": "ist nach Hanau gezogen."}, {"key": "C", "text": "verlangt Schadensersatz für entstandene Beschädigungen."}]'::jsonb, 3, null::jsonb, 1),
    ('lvs2', 'B', 'Antworten Sie Herrn Zaun im Namen von Monika Kühne.', null::jsonb, 0, '{"points": ["Bedauern und Entschuldigung für die Unannehmlichkeiten", "Erklärung der Ursachen (Autopanne und kurzfristiger Personalmangel)", "Zusage des Pünktlichen Eintreffens von zwei Monteuren am Mittwochmorgen", "Bestätigung der Kostenübernahme für die beschädigten Möbelstücke"]}'::jsonb, 0),
    ('hv1', '22', 'Der Chef erklärt Melanie, mit welchen Produkten der Salon arbeitet.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('hv1', '23', 'Im Friseursalon', '[{"key": "A", "text": "dürfen keine Markenprodukte empfohlen werden."}, {"key": "B", "text": "bestellt der Chef jede Woche die Ware selbst."}, {"key": "C", "text": "wird das Trinkgeld regelmäßig unter allen Mitarbeitern aufgeteilt."}]'::jsonb, 3, null::jsonb, 1),
    ('hv1', '24', 'Die Kollegen einigen sich darauf, wer wann Urlaub nehmen kann.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('hv1', '25', 'In den Sommerferien', '[{"key": "A", "text": "können nur Mitarbeiter mit Kindern Urlaub machen."}, {"key": "B", "text": "möchte Sandra für eine größere Reise verreisen."}, {"key": "C", "text": "will Mustafa die ersten beiden Wochen freinehmen."}]'::jsonb, 3, null::jsonb, 3),
    ('hv1', '26', 'Frau Schulz braucht mehrere neue Kaffeemaschinen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 4),
    ('hv1', '27', 'Frau Schulz findet das Gerät ESAM 320 passend, obwohl es', '[{"key": "A", "text": "recht groß ist."}, {"key": "B", "text": "sich nicht selbst reinigen kann."}, {"key": "C", "text": "ziemlich laut im Betrieb ist."}]'::jsonb, 3, null::jsonb, 5),
    ('hv2', '28', 'Person 1 (Melanie und neue Kollegin)', null::jsonb, 3, null::jsonb, 0),
    ('hv2', '29', 'Person 2 (Grippeschutzimpfung im Betrieb)', null::jsonb, 3, null::jsonb, 1),
    ('hv2', '30', 'Person 3 (Infoblatt Händewaschen)', null::jsonb, 3, null::jsonb, 2),
    ('hv2', '31', 'Person 4 (Schreibtisch und Rückenprobleme)', null::jsonb, 3, null::jsonb, 3),
    ('hv3', '32', 'Die neue Werbekampagne', '[{"key": "A", "text": "ist bereits vollständig abgeschlossen."}, {"key": "B", "text": "wird ausschließlich intern konzipiert."}, {"key": "C", "text": "gestaltet eine externe Agentur."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'Die sozialen Medien werden dazu genutzt, um', '[{"key": "A", "text": "aktiv neue Bewerber zu suchen."}, {"key": "B", "text": "offizielle Vorstellungsgespräche zu führen."}, {"key": "C", "text": "die Bewerber vorab besser kennenzulernen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Das Beleuchtungskonzept der bisherigen Filialen', '[{"key": "A", "text": "führte zu Unzufriedenheit bei der Kundschaft."}, {"key": "B", "text": "soll unverändert übernommen werden."}, {"key": "C", "text": "war besonders vorteilhaft in Umkleidekabinen."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Im neuen Frankfurter Modehaus wird', '[{"key": "A", "text": "ausschließlich billige Kleidung angeboten."}, {"key": "B", "text": "nur exklusive Designermode geführt."}, {"key": "C", "text": "auch Kleidung mit hoher Qualität verkauft."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Jana', '[{"key": "A", "text": "benötigt einen Internetzugang im Besprechungsraum."}, {"key": "B", "text": "besorgt selbst einen Beamer für die Veranstaltung."}, {"key": "C", "text": "stellt einen Flipchart in den Raum."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Felix', '[{"key": "A", "text": "bittet um einen Terminvorschlag zur Besprechung der Schulung."}, {"key": "B", "text": "hat bereits alle verbindlichen Software-Angebote erhalten."}, {"key": "C", "text": "soll selbst an einer Kundenschulung teilnehmen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Kathrin Schönberner', '[{"key": "A", "text": "befürchtet wegen Lieferverzögerungen Kunden an die Konkurrenz zu verlieren."}, {"key": "B", "text": "hat bereits eine neue Spedition gefunden."}, {"key": "C", "text": "hat Lieferfristen nicht beachtet."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Daniel Meyer möchte wissen,', '[{"key": "A", "text": "ob alle Telefonapparate ausgetauscht werden müssen."}, {"key": "B", "text": "wer den Kollegen die neue Anlage erklärt."}, {"key": "C", "text": "wie lange die Telefonanlage beim Austausch nicht funktionieren wird."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Anja', '[{"key": "A", "text": "kann nicht zur Besprechung kommen."}, {"key": "B", "text": "hat keinen Überblick über die Verkaufszahlen und bittet um Vertretung."}, {"key": "C", "text": "steht nicht auf der Teilnehmerliste."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie die Kundenanfrage:', null::jsonb, 0, '{"points": ["Name des Anrufers (Herr Meßner, M-E-S-S-N-E-R, Firma Karcher & Söhne)", "Telefonnummer (04133 784 30 09)", "Anlass (Tischreservierung für 5 Personen am Freitag um 19:30 Uhr)", "Wünsche (Menü 1 für alle Gäste vorbereiten, Auskunft über Gästeparkplätze)", "Zu erledigen (Rückruf zur Bestätigung der Reservierung)"]}'::jsonb, 0),
    ('sb1', '46', '… und Sie mich (46) Probearbeiten einladen. …', null::jsonb, 0.5, null::jsonb, 0),
    ('sb1', '47', '… Gelegenheit, meine Fähigkeiten (47) Beweis zu stellen. …', null::jsonb, 0.5, null::jsonb, 1),
    ('sb1', '48', '… Ich freue mich (48), bei dieser Gelegenheit …', null::jsonb, 0.5, null::jsonb, 2),
    ('sb1', '49', '… bei dieser Gelegenheit (49) einen ersten Einblick in die Arbeitsabläufe …', null::jsonb, 0.5, null::jsonb, 3),
    ('sb1', '50', '… Gibt es noch irgendwas, (50) ich vorher besorgen muss? …', null::jsonb, 0.5, null::jsonb, 4),
    ('sb1', '51', '… Brauche ich (51) noch eine ärztliche Bescheinigung vom Gesundheitsamt? …', null::jsonb, 0.5, null::jsonb, 5),
    ('sb2', '52', '… an die von (52) Lieferadresse. …', '[{"key": "A", "text": "Ihnen angegebene"}, {"key": "B", "text": "ihr angeordnete"}, {"key": "C", "text": "mir angeführte"}]'::jsonb, 0.5, null::jsonb, 0),
    ('sb2', '53', '… innerhalb von sieben Tagen nach Lieferung (53). …', '[{"key": "A", "text": "drei Prozent Ermäßigung bezahlen"}, {"key": "B", "text": "drei Prozent Rabatt wünschen"}, {"key": "C", "text": "drei Prozent Skonto gewähren"}]'::jsonb, 0.5, null::jsonb, 1),
    ('sb2', '54', '… bis 30 Tage nach Wareneingang (54). …', '[{"key": "A", "text": "beglichen werden"}, {"key": "B", "text": "dokumentiert werden"}, {"key": "C", "text": "verhandelt werden"}]'::jsonb, 0.5, null::jsonb, 2),
    ('sb2', '55', '… Die detaillierten Konditionen (55) unseren allgemeinen Geschäftsbedingungen …', '[{"key": "A", "text": "entnehmen Sie bitte"}, {"key": "B", "text": "erfahren Sie direkt"}, {"key": "C", "text": "finden Sie gerne"}]'::jsonb, 0.5, null::jsonb, 3),
    ('sb2', '56', '… Bitte halten Sie hierzu Ihre (56). …', '[{"key": "A", "text": "Auftragsnummer bereit"}, {"key": "B", "text": "Kundennummer fest"}, {"key": "C", "text": "Rechnungsnummer an"}]'::jsonb, 0.5, null::jsonb, 4),
    ('sb2', '57', '… Wir versprechen Ihnen eine zuverlässige (57) und sind sicher, …', '[{"key": "A", "text": "Ausführung Ihres Auftrags"}, {"key": "B", "text": "Bearbeitung Ihrer Anfrage"}, {"key": "C", "text": "Durchführung Ihrer Arbeit"}]'::jsonb, 0.5, null::jsonb, 5)
) as v(section_id, item_id, text, options, points, meta, sort)
