insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Die Lebensmittelbranche boomt: Der Einzelhandel ist einer der größten und umsatzstärksten Wirtschaftszweige national und international. Es werden dort ständig qualifizierte Mitarbeiter gesucht. Allein in Hessen werden jährlich 160.000 junge Menschen ausgebildet. Der Einzelhandel ist außerdem krisenfest, denn gegessen wird immer."}, {"key": "B", "text": "Aus Fehlern anderer lernen: Viele Unternehmer machen zu Beginn ihrer Selbstständigkeit ähnliche Fehler. Heute weiß man, dass ein durchdachter Businessplan und eine genaue Konkurrenzanalyse unverzichtbar sind. Worauf es noch ankommt, erfährst du in den Tipps des Erfolgscoachs Gregor Daub."}, {"key": "C", "text": "Chancen im Einzelhandel: Die FOOD Unternehmensgruppe betreibt Supermärkte in zehn Ländern Europas. Der Branchenriese möchte weiter expandieren und hat gerade die Filialen der Jennings GmbH übernommen. Erfahrene Mitarbeiter finden dort interessante Möglichkeiten zur beruflichen Weiterentwicklung."}, {"key": "D", "text": "Gute Nachrichten für gekündigte Mitarbeiter: Die Tankstellenkette Fairtank hat Bankrott angekündigt und schließt zum 31. März ihre 25 Filialen in Brandenburg. Rund 100 Mitarbeiter sind betroffen und suchen nun einen neuen Job. Für einige von ihnen gibt es eine Lösung: Tankstellen in der Umgebung haben ihre Unterstützung zugesagt und versprochen, Mitarbeiter von Fairtank zu übernehmen."}, {"key": "E", "text": "Was nun? Egal, ob die ganze Firma pleitegeht, eine Abteilung dichtmacht oder nur der eigene Job weg ist, eine Entlassung ist immer ein Schock. Arbeitsmarktexpertin Caroline Cuyper erklärt, was man als Angestellter tun muss, um möglichst schnell eine neue Stelle zu bekommen."}, {"key": "F", "text": "Neue Kursreihe bei Arcadio: Ab sofort bietet das Institut Arcadio neben seinen Computerkursen für Senioren auch Weiterbildungen für Teilnehmer mit geringen Deutschkenntnissen an. Das Besondere daran: Die Dozenten verwenden eine einfache Sprache. Was hinter diesem innovativen Konzept steht, erzählt der Institutsgründer Benjamin von Adler im Interview."}, {"key": "G", "text": "Wenn die Mitarbeiter kündigen: Immer mehr Mitarbeiter kündigen und verlassen ihre Firma. Und zwar selbst dann, wenn sie mehr Gehalt bekommen als bei der Konkurrenz. Die Unternehmensberatung Schindler hat die häufigsten Gründe analysiert, warum sich Angestellte entscheiden, ihren Job zu wechseln."}, {"key": "H", "text": "Bildung im neuen Zeitalter: Schneller technologischer Fortschritt, Globalisierung und Veränderungen auf dem Arbeitsmarkt haben dazu geführt, dass Fortbildungen im Beruf eine immer wichtigere Rolle spielen. Zunehmend werden Online-Kurse und Webinare am Computer angeboten, die den Teilnehmern maximale Flexibilität versprechen. Wo findet man passende Fortbildungen?"}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 15, 'Lesen Sie die Texte und die Aufgaben 6 bis 9. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Einführungstag", "b": true}, {"t": "Unsere Personalreferentin führt mehrmals jährlich einen Einführungstag für unsere neuen Mitarbeiterinnen und Mitarbeiter durch, an dem diese mit unterschiedlichen Arbeitsbereichen sowie den rechtlichen und organisatorischen Prozessen vertraut gemacht werden. Wir möchten darauf hinweisen, dass die Teilnahme an einer solchen Informationsveranstaltung verpflichtend ist. Am Einführungstag besteht außerdem die Möglichkeit, Kolleginnen und Kollegen aus anderen Abteilungen kennenzulernen. Die Abteilungsleiter werden bei dieser Gelegenheit in kurzen Worten einen Einblick in den Tätigkeitsbereich ihrer Teams geben.", "b": false}, {"t": "Da unser Unternehmen in einem hochsensiblen Bereich arbeitet, haben wir für unser gesamtes Gebäude ein komplexes Sicherheitssystem. Auch dieses stellen wir Ihnen im Rahmen des Orientierungstages im Detail vor. Weitere Einzelheiten zu diesem Tag, wie den Treffpunkt und den Ablauf, finden Sie in dieser Mappe. Eine gesonderte Anmeldung ist nicht erforderlich.", "b": false}, {"t": "Für Rückfragen zum Einführungstag steht die Personalabteilung gerne zur Verfügung.", "b": false}]}, {"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Datenschutz", "b": true}, {"t": "Ihre im Unternehmen verwendeten Passwörter dürfen unter keinen Umständen weitergegeben und müssen regelmäßig alle sechs Monate geändert werden. Bitte verwenden Sie keine Passwörter, die Sie auch für private Konten nutzen, und generieren Sie sichere Passwörter mit einem Passwortgenerator. USB-Sticks und Ihnen unbekannte Geräte sind vor Inbetriebnahme in isolierter Umgebung zu prüfen. Es darf keine Software aus dem Internet heruntergeladen oder selbstständig auf dem Arbeitslaptop oder dem PC installiert werden. Außerdem ist es untersagt, Daten lokal abzuspeichern.", "b": false}, {"t": "Bitte achten Sie bei Dienstreisen darauf, Ihren Laptop vor Fremden zu sichern! Bedenken Sie bitte auch, dass bei der Arbeit möglicherweise vertrauliche Informationen auf Ihrem Bildschirm zu sehen sind. Schützen Sie diese vor fremden Blicken.", "b": false}, {"t": "Vertrauliche Telefonate dürfen nicht in der Öffentlichkeit geführt werden. Die private Nutzung von Diensthandys oder Laptops ist untersagt.", "b": false}, {"t": "Vertrauliche und personenbezogene Daten müssen nach Dienstschluss verschlossen werden. Sie dürfen zudem nicht länger als unbedingt erforderlich aufgehoben oder gespeichert werden. Über interne Unternehmensangelegenheiten oder Dienstgeheimnisse ist Verschwiegenheit zu wahren. Unterlagen, Datenträger, Abschriften oder Kopien dürfen nicht weitergegeben werden oder versehentlich in die Hände unbefugter Personen gelangen. Vertrauliche Daten in Papierform sind in dafür bereitgestellten Schreddern zu vernichten.", "b": false}, {"t": "Bitte melden Sie ungewöhnliche Vorkommnisse oder Feststellungen umgehend der Geschäftsführung oder unserem Datenschutzbeauftragten, Herrn Dr. Sevici. Er ist unter der Durchwahl -33 zu erreichen und steht Ihnen auch bei Fragen bezüglich des Datenschutzes in unserem Unternehmen zur Verfügung.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Beiträge a–f aus einem Online-Forum. Welcher Beitrag passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Andres: Wenn du in Sportkleidung in die Firma kommst und dich dort noch umziehst, ist das Privatsache. Du musst dafür sorgen, dass du pünktlich mit deiner Arbeit beginnen kannst. In diesem Fall ist die Umkleidezeit keine Arbeitszeit."}, {"key": "B", "text": "Paula: Der Weg zur Arbeit ist private Zeit. Du trägst die Verantwortung dafür, pünktlich vor Ort zu sein, egal wie weit dein Weg ist. Wenn du z.B. im Stau stehst oder die S-Bahn streikt und du deshalb zu spät kommst, musst du die Zeit nacharbeiten."}, {"key": "C", "text": "Raimund: Arbeitnehmer/innen haben in der Regel alle zwei Jahre Anspruch auf fünf Tage Bildungsurlaub. Die Gesetze sind aber nicht in jedem Bundesland gleich. So variiert zum Beispiel die Anzahl der Tage für Bildungsurlaub je nachdem, ob du Voll- oder Teilzeit tätig bist."}, {"key": "D", "text": "Hubert: Ich finde das Tragen von Dienstkleidung absolut veraltet. Warum müssen alle im Unternehmen gleich gekleidet sein? Jeder Mensch hat doch seinen eigenen Stil, mit dem er sich wohlfühlt. Ich kann verstehen, dass du die Uniform nicht auch noch im Zug tragen möchtest."}, {"key": "E", "text": "Yvonne: Wenn du selbst entscheidest, eine Fortbildung zu besuchen, und das vorher nicht mit deinem Arbeitgeber absprichst, ist das reines Privatvergnügen. Schickt dein Chef dich allerdings seinerseits auf ein Seminar, handelt es sich um Arbeitszeit."}, {"key": "F", "text": "Winfried: Das ist ein schwieriges Thema. Wenn du während der Reise zum Beispiel deinen Termin vorbereitest oder mit dem Laptop ein Protokoll schreibst, ist das Arbeitszeit. Wenn du dich aber mit privaten Dingen wie einem Roman oder einem privaten Telefonat beschäftigst, gilt das als Freizeit."}, {"key": "X", "text": "Keine Antwort passt"}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 10, 'Lesen Sie das Protokoll und die Aufgaben 14 bis 18. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll 27.08.20XX, 10.00 bis 11.30 Uhr", "b": true}, {"t": "Konferenzraum Rhein-Main, Am Wegesrand 12, 63345 Frankfurt", "b": false}, {"t": "Anwesende: Thomas Köhler (TK, Werkstatt), Brigitte Turner (BT, Personal), Gerd Schneider (GS, Buchhaltung), Hilde Bruhns (HB, Buchhaltung)", "b": false}, {"t": "Entschuldigt: Kari Muster (KM, Lager)", "b": false}, {"t": "Sitzungsleitung: Gerd Schneider", "b": false}, {"t": "Protokollführung: Thomas Köhler", "b": false}, {"t": "Tagesordnungspunkte:", "b": true}, {"t": "1. Begrüßung und Eröffnung der Sitzung", "b": false}, {"t": "2. Erste-Hilfe-Kurs", "b": false}, {"t": "3. Homeoffice", "b": false}, {"t": "4. Personelle Engpässe Buchhaltung", "b": false}, {"t": "5. Betriebsausflug", "b": false}, {"t": "6. Sonstiges", "b": false}, {"t": "TOP 1 Begrüßung und Eröffnung der Sitzung", "b": true}, {"t": "GS eröffnet die Sitzung, begrüßt alle Anwesenden und stellt den Kolleg*innen Hilde Bruhns vor, die seit dem 1. August in der Abteilung Buchhaltung für die Auszahlung der Gehälter etc. zuständig ist.", "b": false}, {"t": "TOP 2 Erste-Hilfe-Kurs", "b": true}, {"t": "TK berichtet, dass es vor Kurzem zu einem Unfall in der Werkstatt gekommen ist, bei dem ein Kollege am Arm verletzt wurde und stark geblutet hat. Obwohl regelmäßig Sicherheitsunterweisungen für die Mitarbeitenden im Lager und in der Werkstatt stattfinden, reagierte nur ein Kollege ruhig und besonnen und war in der Lage, den Verletzten zu versorgen und dann Hilfe zu holen. Die anderen wussten nicht, was sie tun sollten. Auch in der Marketingabteilung gab es eine Situation, in der einer Kollegin wohl wegen der Hitze schwindlig wurde und ein Krankenwagen gerufen werden musste, da niemand von den Mitarbeiter*innen helfen konnte.", "b": false}, {"t": "TK schlägt deshalb vor, einen Erste-Hilfe-Kurs im Unternehmen zu organisieren, an dem alle interessierten Angestellten teilnehmen können. TK hat bereits mit dem Roten Kreuz gesprochen. Es wäre möglich, dort kurzfristig einen solchen Kurs an zwei Freitagsterminen zu buchen.", "b": false}, {"t": "TOP 3 Homeoffice", "b": true}, {"t": "BT stellt dar, dass immer wieder Mitarbeiter*innen den Wunsch an sie herantragen, den einen oder anderen Tag in der Woche von zu Hause aus zu arbeiten, wenn sie Aufgaben zu erledigen haben, die eine Anwesenheit im Büro nicht unbedingt erforderlich machen.", "b": false}, {"t": "BT steht diesem Wunsch offen gegenüber. Durch diese Möglichkeit könnten die Mitarbeiter*innen die Zeit für den Arbeitsweg sparen und sich ihre Arbeitszeit flexibler einteilen. Das würde sicher erheblich zur Mitarbeiterzufriedenheit beitragen. Den Mitarbeiter*innen, die im Homeoffice arbeiten, müssten firmeneigene Laptops und Diensthandys zur Verfügung gestellt werden. Da aber bereits einige mobile Geräte im Unternehmen vorhanden sind, würde das keine signifikanten Mehrkosten bedeuten. Sollte sich das Arbeitsmodell „Homeoffice” bewähren, könnte für die Kolleg*innen, die regelmäßig von zu Hause aus arbeiten, ein VPN-Tunnel eingerichtet werden, durch den sie sicheren Zugang zu den Daten auf dem Firmenserver erhalten würden.", "b": false}, {"t": "BT bittet bis Mitte der nächsten Woche um Rückmeldungen, was die einzelnen Abteilungsleiter*innen davon halten, bevor sie den Vorschlag der Geschäftsführung vorlegt.", "b": false}, {"t": "TOP 4 Personelle Engpässe in der Buchhaltung", "b": true}, {"t": "GS teilt mit, dass die Buchhaltung zurzeit trotz der Neueinstellung von Frau Bruhns personell unterbesetzt ist. Das Arbeitsaufkommen ist von den derzeit drei Mitarbeiter*innen in der Abteilung nicht mehr zu bewältigen. Im Moment ist auch noch eine Kollegin krank, sodass die verbleibenden Kolleg*innen viele Überstunden machen müssen, um die Arbeit zu schaffen. Er plant, eine weitere Mitarbeiterin oder einen weiteren Mitarbeiter einzustellen.", "b": false}, {"t": "TOP 5 Betriebsausflug", "b": true}, {"t": "HB arbeitet im diesjährigen Team für die Organisation des Betriebsausflugs mit, um so gleich einige Kolleg*innen kennenzulernen. Sie berichtet, dass der Ausflug am 1. Oktober stattfindet. Alle Mitarbeiter*innen treffen sich morgens um 9.00 Uhr vor dem Haupteingang der Firma. Dort werden sie von einem Bus abgeholt und zum Kastell Saalburg gefahren. Vom Parkplatz am Fuße der Burg aus ist eine kleine Wanderung geplant. Am Ziel wartet eine Überraschung. Für das leibliche Wohl ist gesorgt. Die Rückkehr zur Firma ist für 19.00 Uhr am gleichen Tag vorgesehen.", "b": false}, {"t": "TOP 6 Sonstiges", "b": true}, {"t": "Entfällt. Keiner der Anwesenden hat noch Punkte zu besprechen.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19 und 20. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Beschwerde über Druck- und Kopiergerät Lexios", "b": true}, {"t": "Sehr geehrte Frau Aichele,", "b": false}, {"t": "vorgestern wurde von einem Ihrer Mitarbeiter unser fast neues Druck- und Kopiergerät der Marke Lexios zum dritten Mal innerhalb von zwei Wochen geprüft, da bei diesem immer wieder Papierstaus aufgetreten sind. Gestern kam es schon wieder zu einer Fehlermeldung, was zur Folge hatte, dass wir Unterlagen nicht fristgerecht einreichen konnten. Aus diesem Grund haben wir eine für uns sehr wichtige Ausschreibung verpasst. Von einer Schadensersatzforderung sehen wir vorerst ab, wir fordern Sie aber auf, uns umgehend auf Ihre Kosten ein anderes Gerät zu liefern. Es handelt sich hier nämlich eindeutig um einen technischen Fehler, den wir nicht zu verantworten haben. Die Rechnungen für die drei vorangegangenen Technikereinsätze werden wir natürlich nicht bezahlen. Ich erwarte Ihre umgehende Rückmeldung.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Benno Schmidt (Mova GmbH)", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf die Beschwerde.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrer Vorgesetzten:", "b": true}, {"t": "Hallo, schau dir mal die Mail von der Firma Mova an. Laut unserem Techniker lag der Fehler erneut an der falschen Bedienung des Geräts. Antworte Herrn Schmidt bitte und weise ihn höflich darauf hin, dass die Lösung des Problems nicht in unserer Verantwortung liegt. Gerne kommt noch einmal ein Techniker in die Firma und weist die Mitarbeiter*innen kostenfrei in die Bedienung ein. Die Kosten für die Überprüfung des Geräts bleiben die Angelegenheit der Mova GmbH.", "b": false}, {"t": "Viele Grüße", "b": false}, {"t": "Sibyl Aichele", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Personen über ihren Arbeitsplatz sprechen. Welcher der Aussagen a–f passt zu welcher Person?', 'matching', '{"bank": [{"key": "A", "text": "Es ist nicht immer einfach, Platz für neue Kolleg*innen zu schaffen."}, {"key": "B", "text": "Im Großraumbüro kann man mit den Kolleg*innen besser zusammenarbeiten."}, {"key": "C", "text": "Manche Mitarbeiter*innen arbeiten gerne regelmäßig von zu Hause aus."}, {"key": "D", "text": "Manchmal tut der räumliche Abstand zu Kolleg*innen gut."}, {"key": "E", "text": "Neue Arbeitsplatzmodelle können für Unternehmen attraktiv sein."}, {"key": "F", "text": "Über die Neugestaltung des Arbeitsplatzes muss nachgedacht werden."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 4, 'Sie hören eine Information für Mitarbeiterinnen und Mitarbeiter. Wählen Sie bei den Aufgaben 32 bis 35 die richtige Lösung.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 5, 'Sie hören fünf kurze Telefongespräche oder Ansagen. Zu jedem Text gibt es eine Aufgabe. Wählen Sie die richtige Lösung.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Beschwerde Getränkelieferung", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Stefan Wolff (Restaurant Ätna):", "b": false}, {"t": "„Stefan Wolff, Restaurant Ätna, guten Tag. Wir haben für heute Getränke für eine Veranstaltung mit über 200 Personen bestellt, aber leider ist die Lieferung noch nicht da und es ist bereits 11 Uhr. Wir warten auf 50 Kästen Wasser und 15 gemischte Saftkisten. Die Sachen müssen bis spätestens 14:30 Uhr bei uns sein, da wir noch alles vorbereiten müssen. Bitte schicken Sie so schnell wie möglich die bestellten Getränke oder geben Sie Bescheid, wann wir mit der Lieferung rechnen können. Sollte ich bis 12 Uhr nichts von Ihnen gehört haben, muss ich versuchen, die Sachen bei einem anderen Getränkemarkt zu bekommen. Das war dann aber auch unser letzter Auftrag für Sie. Sie erreichen mich unter der Nummer 0162 744 642 8. Mein Name ist Wolff. W-O-L-F-F.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9, "audio": "telc-b2-m06-hvs.mp3", "audioPlays": 2}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–j passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "DASS"}, {"key": "B", "text": "DESHALB"}, {"key": "C", "text": "INNERHALB"}, {"key": "D", "text": "OB"}, {"key": "E", "text": "WÄHREND"}, {"key": "F", "text": "WEIL"}, {"key": "G", "text": "WIE"}, {"key": "H", "text": "ZU"}, {"key": "I", "text": "ZUM"}, {"key": "J", "text": "ZUR"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Fragen zur Ausbildung", "b": true}, {"t": "Sehr geehrte Damen und Herren,", "b": false}, {"t": "ich habe mich sehr darüber gefreut, dass ich meine Ausbildung (46) Kauffrau für Büromanagement im August in Ihrem Unternehmen beginnen kann.", "b": false}, {"t": "Ich würde gern wissen, (47) die Ausbildung zeitlich organisiert ist. Im Vorstellungsgespräch teilten Sie mir mit, dass sich die Ausbildung in theoretische und praktische Blöcke teilt. Im Gegensatz (48) praktischen Block müsste ich mir für die Zeit der Theorie ein Zimmer mieten. (49) wäre es wichtig, so schnell wie möglich die Termine zu wissen. In diesem Zusammenhang möchte ich nachfragen, (50) es möglich wäre, dass die Firma für die Theoriephasen einen Zuschuss für die Miete bezahlt.", "b": false}, {"t": "Außerdem würde ich gern erfahren, wer mein Ansprechpartner (51) des praktischen Teils der Ausbildung sein wird.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Anna Ivanova", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung passt am besten?', 'mc', '{"passages": [{"paragraphs": [{"t": "Angebot", "b": true}, {"t": "Sehr geehrte Damen und Herren,", "b": false}, {"t": "wir danken Ihnen für Ihre Anfrage vom 08.12.20xx und unterbreiten Ihnen (52) acht Schreibtischcontainer MV 17 WW weiß zum Preis von je 156,99 Euro netto. Ab einem Auftragswert von 900,00 Euro liefern wir frei Haus, ansonsten fällt eine Lieferpauschale (53) von 39,00 Euro an.", "b": false}, {"t": "Gerne montieren wir die Möbel auch vor Ort. Die Kosten für den Aufbau (54) nach dem Warenwert und betragen 20% des Nettopreises. Natürlich besteht auch (55) die Ware in unserem Lager abzuholen und selbst aufzubauen.", "b": false}, {"t": "(56) ist 14 Tage bindend. Wir würden uns sehr freuen, (57) zu erhalten. Sollten Sie noch Fragen haben, stehen wir Ihnen gerne jederzeit zur Verfügung.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Lars Walter", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-06'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Silvie ist gelernte Verkäuferin und möchte in ihrem Job aufsteigen.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Brian sucht Computerkurse, die er von zu Hause aus machen kann.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Carl ist Umwelttechniker und möchte seine eigene Beratungsagentur gründen.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Mira ist unsicher, wie es nach ihrem Arbeitsplatzverlust weitergehen soll.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Karim sucht einen Ausbildungsplatz in einer sicheren Branche.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Alle Mitarbeiter müssen ein paar Mal pro Jahr am Einführungstag teilnehmen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'Am Einführungstag', '[{"key": "A", "text": "müssen sich die Teilnehmenden in der Personalabteilung melden."}, {"key": "B", "text": "stellt ein Abteilungsleiter alle Kolleginnen und Kollegen vor."}, {"key": "C", "text": "werden neue Mitarbeitende in die Sicherheitsregeln im Unternehmen eingeführt."}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Die Mitarbeitenden dürfen ihre Passwörter frühestens alle sechs Monate ändern.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Vertrauliche Daten', '[{"key": "A", "text": "dürfen nicht auf dem PC gespeichert werden."}, {"key": "B", "text": "müssen nach einer bestimmten Zeit gelöscht werden."}, {"key": "C", "text": "sollen ausgedruckt und abgeheftet werden."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Claudia: „Ich muss während der Arbeit eine Uniform tragen. Mir ist es unangenehm, die schon morgens in der Bahn anzuhaben, und ich möchte mich lieber im Hotel umziehen. Muss ich dafür früher kommen oder gilt die Umkleidezeit als Arbeitszeit?“', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Maisel: „Gestern war ich für einen Tag bei einem Kunden in Norddeutschland. Ich bin mit dem Zug gefahren und habe während der Fahrt gelesen. Insgesamt war ich elf Stunden unterwegs und habe Überstunden geltend gemacht. Die will mein Arbeitgeber nicht anerkennen.“', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Cristof: „Ich war am Wochenende auf einer Fortbildung, die für meine Arbeit relevant war. Ich wollte mir jetzt einen Urlaubstag gutschreiben lassen, aber meine Chefin sagt, das sei meine private Angelegenheit, da sie die Fortbildung nicht angeordnet hat. Stimmt das?“', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Samira: „Ich fahre morgens mit dem Fahrrad in die Firma, bin immer pünktlich um 9.00 Uhr da und mache mich dann fertig. Ab sofort soll ich früher kommen und darf mich nicht mehr während der Arbeitszeit umziehen. Ist das korrekt?“', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Frau Bruhns', '[{"key": "A", "text": "arbeitet seit einigen Wochen in der Buchhaltung."}, {"key": "B", "text": "bezahlt die Gehälter der Mitarbeiter*innen."}, {"key": "C", "text": "nimmt bald ihre Tätigkeit auf."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Der Erste-Hilfe-Kurs', '[{"key": "A", "text": "findet jeden Freitag statt."}, {"key": "B", "text": "ist für alle Mitarbeiter*innen verpflichtend."}, {"key": "C", "text": "wird vom Roten Kreuz durchgeführt."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Homeoffice', '[{"key": "A", "text": "erfordert die Anschaffung neuer Arbeitsgeräte."}, {"key": "B", "text": "verringert die Arbeitszeit der Mitarbeitenden."}, {"key": "C", "text": "wird von vielen Mitarbeitenden gewünscht."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'In der Abteilung Buchhaltung', '[{"key": "A", "text": "gibt es zu viele Beschäftigte."}, {"key": "B", "text": "sind viele Kolleg*innen erkrankt."}, {"key": "C", "text": "soll eine Stelle ausgeschrieben werden."}]'::jsonb, 3, null::jsonb, 3),
